    $selectedRecipients=!empty($rowDraft['include'])||!empty($rowDraft['exclude'])||!empty($rowDraft['exclude_tag'])||!empty($rowDraft['recipient_rules']['rules'])||($rowDraft['target']??'all')!=='all';
    $recipientLabel=!empty($rowDraft['recipients_saved'])?($selectedRecipients?'Selected subscribers':'All subscribers'):(isset($row['delivery_count'])?'Campaign recipients':'Not selected');
    $thumbnail='';foreach($rowDraft['design']['rows']??[]as$designRow){foreach($designRow['columns']??[]as$column){foreach($column as$block){if(($block['type']??'')==='image'){try{$thumbnail=audienceDesignImage($block['image']??'');}catch(InvalidArgumentException){}if($thumbnail!=='')break 3;}}}}
?>
<tr>
    <td class="campaign-select-column"><?php if($canManage): ?><input type="checkbox" name="selected[]" value="<?= $row['id'] ?>" aria-label="Select <?= $h($row['name']) ?>" data-campaign-select-item><input type="hidden" name="versions[<?= $row['id'] ?>]" value="<?= $row['version'] ?>"><?php endif; ?></td>
    <td data-campaign-column="name"><div class="campaign-name-cell"><span class="campaign-thumbnail" aria-hidden="true"><?php if($thumbnail!==''): ?><img src="<?= $h($thumbnail) ?>" alt="" loading="lazy"><?php else: ?><?php audienceNavIcon(audienceCampaignType($row)==='plain-text'?'text':'mail'); ?><i></i><i></i><i></i><?php endif; ?></span><div><a class="campaign-name" href="<?= $h($url(['view'=>'campaign','id'=>$row['id']])) ?>"><?php audienceNavIcon('mail'); ?><span><?= $h($row['name']) ?></span></a><p class="campaign-subject" title="<?= $h($rowDraft['subject']??'') ?>"><?= isset($rowDraft['subject'])?'Subject: '.$h($rowDraft['subject']):$h($campaignTypes[audienceCampaignType($row)]??'Email') ?></p></div></div></td>
    <td data-campaign-column="date"><time datetime="<?= $h($edited?->format('c')) ?>"><?= $h($edited?->format('D, M j, Y')??'—') ?><small><?= $h($edited?->format('g:i A T')??'') ?></small></time></td>
    <td data-campaign-column="status"><span class="campaign-status" data-status="<?= $h($row['status']) ?>"><?= $h(ucfirst($row['status'])) ?></span><?php if($statusDate): ?><time class="campaign-status-date" datetime="<?= $h($statusDate->format('c')) ?>"><?= $h($statusDate->format('D, M j, Y')) ?><small><?= $h($statusDate->format('g:i A T')) ?></small></time><?php endif; ?></td>
    <td data-campaign-column="analytics"><?php if(isset($rowMetrics['open_rate'])||isset($rowMetrics['click_rate'])): ?><div class="campaign-analytics"><?php foreach(['open_rate'=>'Opens','click_rate'=>'Clicks']as$metric=>$label): ?><span title="<?= $h(audienceEngagementExplanation()) ?>"><small><?= $label ?></small><?= isset($rowMetrics[$metric])?$h(number_format($rowMetrics[$metric],1)).'%':'—' ?></span><?php endforeach; ?></div><?php else: ?>—<?php endif; ?><?php if(!empty($rowMetrics['awaiting_receipt'])): ?><small><?= (int)$rowMetrics['awaiting_receipt'] ?> pending receipts</small><?php endif; ?></td>
    <td data-campaign-column="recipients"><?= $h($recipientLabel) ?><?php if(isset($row['delivery_count'])): ?><a class="campaign-recipient-count" href="<?= $h($url(['view'=>'campaign-delivery','id'=>$row['id']])) ?>"><?= number_format((int)$row['delivery_count']) ?> recipients</a><?php endif; ?></td>
    <td data-campaign-column="folder"><?php if($row['folder_name']): ?><a href="<?= $h($campaignUrl(['folder'=>$row['folder_id'],'page'=>1])) ?>"><?= $h($row['folder_name']) ?></a><?php else: ?>—<?php endif; ?></td>
    <td data-campaign-column="editor"><span class="campaign-editor" title="<?= $h($row['actor_label']) ?>"><?= $h($row['actor_label']?:'—') ?></span></td>
    <td data-campaign-column="actions"><div class="campaign-row-actions"><div class="campaign-split-action"><a class="audience-button" href="<?= $h($url(['view'=>$row['status']==='sent'?'campaign-delivery':'campaign','id'=>$row['id']])) ?>"><?= $rowAction ?></a><?php if($canManage): ?><button type="button" class="campaign-icon-button" aria-label="More actions for <?= $h($row['name']) ?>" popovertarget="campaign-actions-<?= $row['id'] ?>"><?php audienceNavIcon('chevron'); ?></button><?php endif; ?></div><?php if($canManage): ?><button type="button" class="campaign-icon-button" aria-label="Replicate <?= $h($row['name']) ?>" data-campaign-row='<?= $campaignJson(array_intersect_key($row,array_flip(['id','name','version']))) ?>' data-campaign-op="replicate"><?php audienceNavIcon('copy'); ?></button><div popover id="campaign-actions-<?= $row['id'] ?>" class="audience-action-menu" role="menu" aria-label="Campaign actions"><?php foreach(['rename'=>'Rename','move'=>'Move to folder','delete'=>'Delete','replicate'=>'Replicate']as$op=>$label): ?><button type="button" role="menuitem" data-campaign-row='<?= $campaignJson(array_intersect_key($row,array_flip(['id','name','version']))) ?>' data-campaign-op="<?= $op ?>"><?= $label ?></button><?php endforeach; ?></div><?php endif; ?></div></td>
</tr>
<?php endforeach; ?>
