<div class="campaign-pagination"><span>Showing results <strong><?= $campaignTotal?($campaignPage-1)*25+1:0 ?> – <?= min($campaignPage*25,$campaignTotal) ?></strong> of <?= number_format($campaignTotal) ?></span><div><?php foreach([[1,'«','Go to first page'],[max(1,$campaignPage-1),'‹','Go to previous page']]as[$p,$label,$aria]): ?><a class="audience-button" aria-label="<?= $aria ?>" href="<?= $h($campaignUrl(['page'=>$p])) ?>"><?= $label ?></a><?php endforeach; ?><span>Page <?= $campaignPage ?> of <?= $pages ?></span><a class="audience-button" aria-label="Go to next page" href="<?= $h($campaignUrl(['page'=>min($pages,$campaignPage+1)])) ?>">›</a><a class="audience-button" aria-label="Go to last page" href="<?= $h($campaignUrl(['page'=>$pages])) ?>">»</a></div></div>
